#!/usr/bin/env python3
"""
Multi-Label Stratified Dataset Splitter
"""

import argparse
import csv
import json
import os
import random
from collections import defaultdict
from itertools import combinations


def parse_input_file(input_path):
    """Read input CSV file."""
    data = []
    with open(input_path, 'r', newline='') as f:
        reader = csv.reader(f)
        for row in reader:
            if len(row) >= 2:
                item_id = row[0].strip()
                tags_str = row[1]
                tags = [t.strip() for t in tags_str.split(',')]
                data.append((item_id, tags))
            elif len(row) == 1:
                item_id = row[0].strip()
                data.append((item_id, []))
    return data


def normalize_tags(tags):
    """Normalize tags: deduplicate, sort, return frozenset."""
    return frozenset(sorted(set(tags)))


def get_label_combinations(tags_list):
    """Get all non-empty label combinations as frozensets."""
    unique_tags = sorted(set(tags_list))
    if not unique_tags:
        return set()
    combos = set()
    for r in range(1, len(unique_tags) + 1):
        for combo in combinations(unique_tags, r):
            combos.add(frozenset(combo))
    return combos


def iterative_stratified_split(data, seed=42, train_ratio=0.7, val_ratio=0.15, test_ratio=0.15):
    """Split data using iterative stratification."""
    n = len(data)
    if n == 0:
        return [], [], [], {"samples": {"train": 0, "val": 0, "test": 0}, 
                            "label_distribution": {}, "label_combinations": {}}

    random.seed(seed)

    # Shuffle indices
    indices = list(range(n))
    random.shuffle(indices)

    # Parse tags
    parsed_data = []
    for i in indices:
        item_id, tags = data[i]
        normalized = normalize_tags(tags)
        parsed_data.append((item_id, normalized))

    # Target sizes
    train_size = max(1, int(n * train_ratio))
    val_size = max(1, int(n * val_ratio))
    test_size = max(0, n - train_size - val_size)

    # Build mappings from entity to samples
    label_to_samples = defaultdict(list)
    combo_to_samples = defaultdict(list)
    for idx, (item_id, tags) in enumerate(parsed_data):
        for label in tags:
            label_to_samples[label].append(idx)
        if tags:
            for combo in get_label_combinations(tags):
                combo_to_samples[combo].append(idx)

    # Get all entities with their frequencies
    entities = []
    for label in label_to_samples:
        entities.append(('label', label, label_to_samples[label]))
    for combo in combo_to_samples:
        entities.append(('combo', combo, combo_to_samples[combo]))

    # Sort by frequency (rarest first), then by type and name for determinism
    entities.sort(key=lambda x: (len(x[2]), x[0], str(x[1])))

    # Initialize assignments
    assignment = [-1] * n  # -1=unassigned, 0=train, 1=val, 2=test
    train_count, val_count, test_count = 0, 0, 0
    train_rem, val_rem, test_rem = train_size, val_size, test_size

    # Process each entity
    for entity_type, entity, samples in entities:
        # Get unassigned samples with this entity
        unassigned = [s for s in samples if assignment[s] == -1]
        if not unassigned:
            continue

        # Target distribution for these samples based on ratios
        # But we need to respect remaining capacity
        # Distribute proportionally to remaining capacity

        total_unassigned = len(unassigned)
        if total_unassigned == 0:
            continue

        # Calculate how many should go to each split
        # Use proportional allocation based on remaining capacity
        total_rem = train_rem + val_rem + test_rem
        if total_rem == 0:
            # No room left, just assign to first available
            for s in unassigned:
                assignment[s] = 0  # default to train
                train_count += 1
            continue

        # For each unassigned sample, assign to split with most remaining capacity
        # This is greedy but should work reasonably
        for s in unassigned:
            # Find split with max remaining
            if train_rem >= val_rem and train_rem >= test_rem:
                assignment[s] = 0
                train_rem -= 1
                train_count += 1
            elif val_rem >= train_rem and val_rem >= test_rem:
                assignment[s] = 1
                val_rem -= 1
                val_count += 1
            else:
                assignment[s] = 2
                test_rem -= 1
                test_count += 1

    # Separate by assignment
    train_data = [parsed_data[i] for i in range(n) if assignment[i] == 0]
    val_data = [parsed_data[i] for i in range(n) if assignment[i] == 1]
    test_data = [parsed_data[i] for i in range(n) if assignment[i] == 2]

    # Build report
    label_distribution = {
        "train": defaultdict(int),
        "val": defaultdict(int),
        "test": defaultdict(int)
    }
    for item_id, tags in train_data:
        for label in tags:
            label_distribution["train"][label] += 1
    for item_id, tags in val_data:
        for label in tags:
            label_distribution["val"][label] += 1
    for item_id, tags in test_data:
        for label in tags:
            label_distribution["test"][label] += 1

    label_combinations = {
        "train": defaultdict(int),
        "val": defaultdict(int),
        "test": defaultdict(int)
    }
    for item_id, tags in train_data:
        for combo in get_label_combinations(tags):
            combo_str = ','.join(sorted(combo))
            label_combinations["train"][combo_str] += 1
    for item_id, tags in val_data:
        for combo in get_label_combinations(tags):
            combo_str = ','.join(sorted(combo))
            label_combinations["val"][combo_str] += 1
    for item_id, tags in test_data:
        for combo in get_label_combinations(tags):
            combo_str = ','.join(sorted(combo))
            label_combinations["test"][combo_str] += 1

    def sort_dict(d):
        return {k: d[k] for k in sorted(d.keys())}

    report = {
        "samples": {
            "test": test_count,
            "train": train_count,
            "val": val_count
        },
        "label_combinations": {
            "test": sort_dict(label_combinations["test"]),
            "train": sort_dict(label_combinations["train"]),
            "val": sort_dict(label_combinations["val"])
        },
        "label_distribution": {
            "test": sort_dict(label_distribution["test"]),
            "train": sort_dict(label_distribution["train"]),
            "val": sort_dict(label_distribution["val"])
        }
    }

    return train_data, val_data, test_data, report


def write_output_files(train_data, val_data, test_data, output_dir):
    """Write output CSV files."""
    os.makedirs(output_dir, exist_ok=True)

    with open(os.path.join(output_dir, 'train.csv'), 'w', newline='') as f:
        writer = csv.writer(f)
        for item_id, tags in train_data:
            tags_str = ','.join(tags) if tags else ''
            writer.writerow([item_id, tags_str])

    with open(os.path.join(output_dir, 'val.csv'), 'w', newline='') as f:
        writer = csv.writer(f)
        for item_id, tags in val_data:
            tags_str = ','.join(tags) if tags else ''
            writer.writerow([item_id, tags_str])

    with open(os.path.join(output_dir, 'test.csv'), 'w', newline='') as f:
        writer = csv.writer(f)
        for item_id, tags in test_data:
            tags_str = ','.join(tags) if tags else ''
            writer.writerow([item_id, tags_str])


def main():
    parser = argparse.ArgumentParser(description='Split multi-label dataset')
    parser.add_argument('--input_path', required=True)
    parser.add_argument('--output_dir', required=True)
    parser.add_argument('--seed', type=int, default=42)

    args = parser.parse_args()

    data = parse_input_file(args.input_path)
    train_data, val_data, test_data, report = iterative_stratified_split(
        data, seed=args.seed, train_ratio=0.7, val_ratio=0.15, test_ratio=0.15
    )

    write_output_files(train_data, val_data, test_data, args.output_dir)

    # Write report with sorted keys
    with open(os.path.join(args.output_dir, 'report.json'), 'w') as f:
        json.dump(report, f, indent=2, sort_keys=True)
        f.write('\n')


if __name__ == '__main__':
    main()
