"""
Multi-Label Stratified Dataset Splitter

Implements iterative stratification to split multi-label data into
train/val/test sets while preserving label and label-combination frequencies.
"""

import argparse
import csv
import json
import os
import random
from collections import defaultdict
from itertools import combinations


def parse_input_file(input_path):
    """Read input CSV file (no headers)."""
    data = []
    with open(input_path, 'r', newline='') as f:
        reader = csv.reader(f)
        for row in reader:
            if len(row) >= 2:
                item_id = row[0].strip()
                tags_str = row[1]
                tags = [t.strip() for t in tags_str.split(',')]
                data.append((item_id, tags))
            elif len(row) == 1:
                item_id = row[0].strip()
                data.append((item_id, []))
    return data


def normalize_tags(tags):
    """Normalize tags: deduplicate, sort alphabetically, return frozenset."""
    return frozenset(sorted(set(tags)))


def get_label_combinations(tags_list):
    """
    Get all label combinations of size 2 or more from tags.
    Returns set of frozensets.
    """
    unique_tags = sorted(set(tags_list))
    if len(unique_tags) < 2:
        return set()
    combos = set()
    for r in range(2, len(unique_tags) + 1):
        for combo in combinations(unique_tags, r):
            combos.add(frozenset(combo))
    return combos


def iterative_stratified_split(data, seed=42, train_ratio=0.7, val_ratio=0.15, test_ratio=0.15):
    """
    Split data using iterative stratification.

    Algorithm:
    1. Shuffle samples with seed
    2. Build mappings of samples by label and by label combination
    3. Sort all labels and combos by frequency (rarest first)
    4. For each entity (label or combo), distribute its unassigned samples
       proportionally across splits (70/15/15)
    5. Respect remaining capacity constraints
    """
    n = len(data)
    if n == 0:
        return [], [], [], {"samples": {"test": 0, "train": 0, "val": 0}, 
                            "label_distribution": {}, "label_combinations": {}}

    random.seed(seed)

    # Shuffle indices
    indices = list(range(n))
    random.shuffle(indices)

    # Parse tags
    parsed_data = []
    for i in indices:
        item_id, tags = data[i]
        normalized = normalize_tags(tags)
        parsed_data.append((item_id, normalized))

    # Target sizes (use floats for proportional assignment)
    train_ratio = 0.7
    val_ratio = 0.15
    test_ratio = 0.15

    # Target absolute counts (floor for now, will adjust)
    train_size = max(0, int(n * train_ratio))
    val_size = max(0, int(n * val_ratio))
    test_size = max(0, n - train_size - val_size)

    # Build mappings
    label_to_samples = defaultdict(list)
    combo_to_samples = defaultdict(list)

    for idx, (item_id, tags) in enumerate(parsed_data):
        for label in tags:
            label_to_samples[label].append(idx)
        if len(tags) >= 2:
            for combo in get_label_combinations(tags):
                combo_to_samples[combo].append(idx)

    # Get all entities
    all_entities = []
    for label, samples in label_to_samples.items():
        all_entities.append(('label', label, samples, len(samples)))
    for combo, samples in combo_to_samples.items():
        all_entities.append(('combo', combo, samples, len(samples)))

    # Sort by frequency ascending (rarest first), then by type/name
    all_entities.sort(key=lambda x: (x[3], x[0], str(x[1])))

    # Assignment tracking
    assignment = [-1] * n  # -1=unassigned, 0=train, 1=val, 2=test
    train_count, val_count, test_count = 0, 0, 0
    train_rem, val_rem, test_rem = train_size, val_size, test_size

