        # But respect remaining capacity
        train_target = int(num_unassigned * train_ratio)
        val_target = int(num_unassigned * val_ratio)
        test_target = num_unassigned - train_target - val_target

        # Adjust to not exceed remaining capacity
        # Greedy: assign to train first up to its capacity, etc.

        # Actually, better: assign samples one by one, choosing split based on
        # how close each split is to its target proportion
        # But simpler: use the proportional targets, capped by remaining

        # Distribute train_target to train (if capacity allows)
        assign_to = []
        for _ in range(train_target):
            if train_rem > 0:
                assign_to.append(0)
                train_rem -= 1
            elif val_rem > 0:
                assign_to.append(1)
                val_rem -= 1
            elif test_rem > 0:
                assign_to.append(2)
                test_rem -= 1
            else:
                break

        for _ in range(val_target):
            if val_rem > 0:
                assign_to.append(1)
                val_rem -= 1
            elif test_rem > 0:
                assign_to.append(2)
                test_rem -= 1
            elif train_rem > 0:
                assign_to.append(0)
                train_rem -= 1
            else:
