        for _ in range(test_target):
            if test_rem > 0:
                assign_to.append(2)
                test_rem -= 1
            elif train_rem > 0:
                assign_to.append(0)
                train_rem -= 1
            elif val_rem > 0:
                assign_to.append(1)
                val_rem -= 1
            else:
                break

        # If we still have unassigned samples, assign to any available split
        remaining = num_unassigned - len(assign_to)
        for _ in range(remaining):
            if train_rem > 0:
                assign_to.append(0)
                train_rem -= 1
            elif val_rem > 0:
                assign_to.append(1)
                val_rem -= 1
            elif test_rem > 0:
                assign_to.append(2)
                test_rem -= 1
            else:
                assign_to.append(0)  # fallback

        # Assign samples
        for s, split in zip(unassigned, assign_to[:num_unassigned]):
            assignment[s] = split

