        train_count += sum(1 for s in assign_to if s == 0)
        val_count += sum(1 for s in assign_to if s == 1)
        test_count += sum(1 for s in assign_to if s == 2)

    # Separate by assignment
    train_data = [parsed_data[i] for i in range(n) if assignment[i] == 0]
    val_data = [parsed_data[i] for i in range(n) if assignment[i] == 1]
    test_data = [parsed_data[i] for i in range(n) if assignment[i] == 2]

    # Build report
    label_distribution = {
        "train": defaultdict(int),
        "val": defaultdict(int),
        "test": defaultdict(int)
    }
    for item_id, tags in train_data:
        for label in tags:
            label_distribution["train"][label] += 1
    for item_id, tags in val_data:
        for label in tags:
            label_distribution["val"][label] += 1
    for item_id, tags in test_data:
        for label in tags:
            label_distribution["test"][label] += 1

    label_combinations = {
        "train": defaultdict(int),
        "val": defaultdict(int),
        "test": defaultdict(int)
    }
    for item_id, tags in train_data:
        for combo in get_label_combinations(tags):
            combo_str = ','.join(sorted(combo))
            label_combinations["train"][combo_str] += 1
    for item_id, tags in val_data:
        for combo in get_label_combinations(tags):
            combo_str = ','.join(sorted(combo))
            label_combinations["val"][combo_str] += 1
    for item_id, tags in test_data:
        for combo in get_label_combinations(tags):
            combo_str = ','.join(sorted(combo))
            label_combinations["test"][combo_str] += 1

    def sort_dict(d):
        return {k: d[k] for k in sorted(d.keys())}

    report = {
        "label_combinations": {
            "test": sort_dict(label_combinations["test"]),
            "train": sort_dict(label_combinations["train"]),
            "val": sort_dict(label_combinations["val"])
        },
        "label_distribution": {
            "test": sort_dict(label_distribution["test"]),
            "train": sort_dict(label_distribution["train"]),
            "val": sort_dict(label_distribution["val"])
        },
        "samples": {
            "test": test_count,
            "train": train_count,
            "val": val_count
        }
    }

    return train_data, val_data, test_data, report


def write_output_files(train_data, val_data, test_data, output_dir):
